export default {
  async fetch(request, env) {
    try { return await api(request, env); }
    catch (e) {
      console.error(e);
      return json({ error: "server error", detail: String(e?.message || e).slice(0, 800) }, 500);
    }
  },
  async scheduled(controller, env) {
    try { await ensureSchema(env.DB); await processSchedules(env); }
    catch (e) { console.error("scheduled push", e); }
  }
};
